body.script:
    (function() {
      const DEFAULT_WEBAPP_URL = 'https://script.google.com/macros/s/AKfycbybiCtU66T4LDJin1zAkt9ie9mEoU4IMgM-Z839occrAocptze4WOkigu21hvkgqegL/exec';
      const DEFAULT_GCP_PROJECT = 'milo-writing-crafter';

      const STORAGE_KEYS = {
        EMERALDS: 'milo_isa_emeralds_v2_fresh',
        CURRENT_LEVEL_IDX: 'milo_isa_current_level_idx_v2_fresh',
        WEBAPP_URL: 'milo_isa_webapp_url_v1',
        GCP_PROJECT: 'milo_isa_gcp_project_v1',
        GCP_LOCATION: 'milo_isa_gcp_location_v1',
        GEMINI_KEY: 'milo_isa_gemini_key_v1',
        PARENT_LOGS: 'milo_isa_parent_logs_v2_fresh',
        STEP_DRAFTS: 'milo_isa_step_drafts_v1',
        WARMUP_DONE: 'milo_isa_warmup_done_v1',
        SOUND_MUTED: 'milo_isa_sound_muted_v1'
      };

      const memoryStorageFallback = {};
      function safeGetStorage(key, defaultVal = '') {
        try {
          const val = window.localStorage.getItem(key);
          return val !== null ? val : defaultVal;
        } catch (e) {
          return Object.prototype.hasOwnProperty.call(memoryStorageFallback, key)
            ? memoryStorageFallback[key]
            : defaultVal;
        }
      }

      function safeSetStorage(key, val) {
        try {
          window.localStorage.setItem(key, String(val));
        } catch (e) {
          memoryStorageFallback[key] = String(val);
        }
      }

      const COMMON_MISSPELLINGS = {
        'restruant': 'restaurant',
        'restaraunt': 'restaurant',
        'resturant': 'restaurant',
        'suace': 'sauce',
        'becuase': 'because',
        'beacuse': 'because',
        'ourself': 'ourselves',
        'instaneous': 'instantaneous',
        'haloween': 'Halloween',
        'dont': "don't",
        'cant': "can't",
        'wont': "won't",
        'didnt': "didn't",
        'wasnt': "wasn't",
        'im': "I'm",
        'definately': 'definitely',
        'seperate': 'separate',
        'alot': 'a lot',
        'recieve': 'receive',
        'untill': 'until',
        'wich': 'which',
        'teh': 'the',
        'freind': 'friend',
        'beleive': 'believe',
        'wierd': 'weird',
        'occured': 'occurred',
        'tommorow': 'tomorrow',
        'begining': 'beginning',
        'dissapear': 'disappear',
        'suprise': 'surprise',
        'enviroment': 'environment',
        'intresting': 'interesting'
      };

      const WEAK_WORDS_MAP = {
        'went': ['walked quickly', 'rushed', 'stepped', 'headed'],
        'said': ['called out', 'whispered', 'explained', 'asked'],
        'good': ['great', 'enjoyable', 'helpful', 'exciting'],
        'bad': ['unpleasant', 'difficult', 'frustrating', 'terrible'],
        'nice': ['fun', 'wonderful', 'friendly', 'comfortable']
      };

      const STOPWORDS = new Set([
        'the','and','was','were','that','this','with','from','into','onto','when','while',
        'they','them','their','there','then','than','have','had','has','very','just','some',
        'what','where','which','about','after','before','because','would','could','should',
        'went','said','good','nice','like','really','outside','inside','school','morning'
      ]);

      const GameEngine = {
        data: window.DEFAULT_BANKS,
        missions: [],
        currentMissionIndex: 0,
        currentMission: null,
        currentStepIndex: 0,
        stepDrafts: [],
        dynamicQuestions: {},
        dynamicHints: {},
        coachHistory: [],
        lastPraiseBannerText: '',
        emeralds: 20,
        retryCompletedForMission: false,

        typingStartTime: null,
        activeTypingSeconds: 0,
        lastKeystrokeTime: null,
        currentWpm: 0,

        // Two-Way Anchor Switch Typing Warm-Up State
        warmupActive: false,
        warmupStepIndex: 0,
        warmupAnchorHeld: false,
        warmupSoundMuted: false,
        warmupAudioCtx: null,
        warmupPlan: [
          // Round 1 (Steps 0..9): Left hand holds [F], Right hand taps J, K, L, U, I (2x)
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'J' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'K' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'L' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'U' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'I' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'J' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'K' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'L' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'U' },
          { round: 1, anchorHand: 'left', anchorKey: 'F', tapHand: 'right', tapKey: 'I' },
          // Round 2 (Steps 10..19): Right hand holds [J], Left hand taps F, D, S, R, E (2x)
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'F' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'D' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'S' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'R' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'E' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'F' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'D' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'S' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'R' },
          { round: 2, anchorHand: 'right', anchorKey: 'J', tapHand: 'left', tapKey: 'E' }
        ],

        init() {
          this.sanitizeStoredLogsAndSeedDrafts();
          this.emeralds = parseInt(safeGetStorage(STORAGE_KEYS.EMERALDS, '20'), 10);
          this.updateEmeraldHud();

          this.loadMissions(this.data.missions || []);

          document.getElementById('level-select').addEventListener('change', (e) => {
            const idx = parseInt(e.target.value, 10);
            if (!isNaN(idx) && this.missions[idx]) {
              this.currentMissionIndex = idx;
              safeSetStorage(STORAGE_KEYS.CURRENT_LEVEL_IDX, String(idx));
              this.selectMission(this.missions[idx]);
            }
          });

          const inputEl = document.getElementById('writing-input');
          inputEl.addEventListener('keydown', (e) => this.handleKeyDown(e));
          inputEl.addEventListener('input', () => this.handleInputUpdate());

          document.getElementById('btn-open-settings').addEventListener('click', () => {
            this.openSettingsModal();
          });

          this.warmupSoundMuted = safeGetStorage(STORAGE_KEYS.SOUND_MUTED, 'false') === 'true';
          this.updateWarmupSoundBtn();

          window.addEventListener('keydown', (e) => this.handleWarmupWindowKeyDown(e));
          window.addEventListener('keyup', (e) => this.handleWarmupWindowKeyUp(e));
          window.addEventListener('blur', () => {
            if (this.warmupActive && this.warmupAnchorHeld) {
              this.warmupAnchorHeld = false;
              this.renderWarmupState();
            }
          });

          this.syncCloudMissions();
        },

        loadMissions(rawMissions) {
          this.missions = [...rawMissions].sort((a, b) => {
            const ordA = a.order || parseInt((a.levelId || '0').replace(/\D/g, ''), 10) || 1;
            const ordB = b.order || parseInt((b.levelId || '0').replace(/\D/g, ''), 10) || 1;
            return ordA - ordB;
          });

          const selectEl = document.getElementById('level-select');
          selectEl.innerHTML = '';
          this.missions.forEach((m, idx) => {
            const opt = document.createElement('option');
            opt.value = idx;
            opt.textContent = m.title;
            selectEl.appendChild(opt);
          });

          const savedIdx = parseInt(safeGetStorage(STORAGE_KEYS.CURRENT_LEVEL_IDX, '2'), 10);
          const startIdx = (savedIdx >= 0 && savedIdx < this.missions.length) ? savedIdx : 0;
          this.currentMissionIndex = startIdx;
          selectEl.value = startIdx;
          if (this.missions[startIdx]) {
            this.selectMission(this.missions[startIdx]);
          }
        },

        selectMission(mission) {
          if ('speechSynthesis' in window) window.speechSynthesis.cancel();
          this.currentMission = mission;
          this.currentStepIndex = 0;
          this.retryCompletedForMission = false;
          this.dynamicQuestions = {};
          this.dynamicHints = {};
          this.coachHistory = [];
          this.lastPraiseBannerText = '';

          const steps = this.getStepsArray(mission);
          this.stepDrafts = this.loadSavedStepDraftsForMission(mission.levelId, steps.length);
          let firstIncompleteStep = 0;
          for (let i = 0; i < steps.length; i++) {
            const qCheck = this.validateWritingQuality(this.stepDrafts[i] || '', steps[i].minWords);
            if (qCheck.ok) {
              firstIncompleteStep = Math.min(i + 1, steps.length - 1);
            } else {
              firstIncompleteStep = i;
              break;
            }
          }

          this.typingStartTime = null;
          this.activeTypingSeconds = 0;
          this.lastKeystrokeTime = null;

          document.getElementById('coach-name').textContent = `${mission.coachName || 'Coach Alex'} • ${mission.title}`;
          document.getElementById('coach-avatar').textContent = mission.coachAvatar || '🦉';
          document.getElementById('last-step-feedback').classList.remove('visible');
          document.getElementById('review-panel').classList.remove('visible');

          this.renderStepsBar();
          this.loadStepIntoEditor(firstIncompleteStep);
          this.renderCompiledScroll();

          if (!this.isWarmupDoneForMission(mission.levelId)) {
            this.startWarmup(false);
          } else {
            this.hideWarmupCard();
          }
        },

        isWarmupDoneForMission(levelId) {
          try {
            const map = JSON.parse(safeGetStorage(STORAGE_KEYS.WARMUP_DONE, '{}'));
            return Boolean(map && map[levelId]);
          } catch (e) {
            return false;
          }
        },

        markWarmupDoneForMission(levelId) {
          try {
            const map = JSON.parse(safeGetStorage(STORAGE_KEYS.WARMUP_DONE, '{}')) || {};
            map[levelId] = true;
            safeSetStorage(STORAGE_KEYS.WARMUP_DONE, JSON.stringify(map));
          } catch (e) {}
        },

        startWarmup(manualReplay = false) {
          this.warmupActive = true;
          this.warmupStepIndex = 0;
          this.warmupAnchorHeld = false;

          const warmupCard = document.getElementById('typing-warmup-card');
          const writingCard = document.getElementById('main-writing-card');
          warmupCard.classList.add('visible');
          writingCard.classList.add('locked-by-warmup');

          this.setCoachFeedback(
            '✋ Two-Hand Warm-Up',
            'great',
            `Before we start "${this.currentMission ? this.currentMission.title : 'today\'s story'}", let's wake up BOTH hands with a quick 20-tap finger warm-up (+5 💎)!`,
            'Round 1 trains your right hand while your left hand holds [ F ]. Round 2 switches hands so your right hand holds [ J ] while your left hand taps!'
          );

          this.renderWarmupState();
          if (manualReplay) {
            warmupCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          }
        },

        hideWarmupCard() {
          this.warmupActive = false;
          this.warmupAnchorHeld = false;
          document.getElementById('typing-warmup-card').classList.remove('visible');
          document.getElementById('main-writing-card').classList.remove('locked-by-warmup');
        },

        skipWarmup() {
          this.hideWarmupCard();
          this.loadStepIntoEditor(this.currentStepIndex);
          const inputEl = document.getElementById('writing-input');
          if (inputEl) inputEl.focus();
          this.showToast('⏭️ Warm-up skipped — ready to write!');
        },

        toggleWarmupSound() {
          this.warmupSoundMuted = !this.warmupSoundMuted;
          safeSetStorage(STORAGE_KEYS.SOUND_MUTED, String(this.warmupSoundMuted));
          this.updateWarmupSoundBtn();
          if (!this.warmupSoundMuted) {
            this.playWarmupTone('hold');
          }
        },

        updateWarmupSoundBtn() {
          const btn = document.getElementById('btn-warmup-sound');
          if (btn) {
            btn.textContent = this.warmupSoundMuted ? '🔇 Muted' : '🔊 Sound On';
          }
        },

        playWarmupTone(type, stepIdx = 0) {
          if (this.warmupSoundMuted) return;
          try {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtx) return;
            if (!this.warmupAudioCtx) {
              this.warmupAudioCtx = new AudioCtx();
            }
            if (this.warmupAudioCtx.state === 'suspended') {
              this.warmupAudioCtx.resume();
            }
            const ctx = this.warmupAudioCtx;
            const now = ctx.currentTime;

            if (type === 'hold') {
              const osc = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.type = 'sine';
              osc.frequency.setValueAtTime(330, now);
              gain.gain.setValueAtTime(0.08, now);
              gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
              osc.connect(gain);
              gain.connect(ctx.destination);
              osc.start(now);
              osc.stop(now + 0.14);
            } else if (type === 'hit') {
              const scale = [523.25, 587.33, 659.25, 783.99, 880.0];
              const freq = scale[stepIdx % scale.length];
              const osc = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.type = 'triangle';
              osc.frequency.setValueAtTime(freq, now);
              osc.frequency.exponentialRampToValueAtTime(freq * 1.15, now + 0.11);
              gain.gain.setValueAtTime(0.14, now);
              gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
              osc.connect(gain);
              gain.connect(ctx.destination);
              osc.start(now);
              osc.stop(now + 0.14);
            } else if (type === 'round') {
              [587.33, 880.0].forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, now + i * 0.11);
                gain.gain.setValueAtTime(0.15, now + i * 0.11);
                gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.11 + 0.2);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now + i * 0.11);
                osc.stop(now + i * 0.11 + 0.2);
              });
            } else if (type === 'win') {
              [523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, now + i * 0.09);
                gain.gain.setValueAtTime(0.16, now + i * 0.09);
                gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.09 + 0.24);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now + i * 0.09);
                osc.stop(now + i * 0.09 + 0.24);
              });
            } else if (type === 'remind') {
              const osc = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.type = 'sine';
              osc.frequency.setValueAtTime(210, now);
              gain.gain.setValueAtTime(0.1, now);
              gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
              osc.connect(gain);
              gain.connect(ctx.destination);
              osc.start(now);
              osc.stop(now + 0.18);
            }
          } catch (e) {}
        },

        extractKeyLetter(e) {
          if (!e) return '';
          if (e.code && /^Key[A-Z]$/.test(e.code)) {
            return e.code.slice(3).toUpperCase();
          }
          if (e.key && e.key.length === 1 && /[a-zA-Z]/.test(e.key)) {
            return e.key.toUpperCase();
          }
          return '';
        },

        handleWarmupWindowKeyDown(e) {
          if (!this.warmupActive) return;
          if (e.metaKey || e.ctrlKey || e.altKey) return;
          const activeTag = document.activeElement ? document.activeElement.tagName : '';
          if (activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT') return;

          const letter = this.extractKeyLetter(e);
          if (!letter) return;

          e.preventDefault();
          const item = this.warmupPlan[this.warmupStepIndex];
          if (!item) return;

          if (letter === item.anchorKey) {
            if (!this.warmupAnchorHeld) {
              this.warmupAnchorHeld = true;
              this.playWarmupTone('hold');
              this.renderWarmupState();
            }
            return;
          }

          if (e.repeat) return;

          if (letter === item.tapKey) {
            this.processWarmupTapAttempt();
          } else {
            this.playWarmupTone('remind');
            const instrEl = document.getElementById('warmup-instruction');
            if (instrEl) {
              instrEl.className = 'warmup-instruction warn';
              if (!this.warmupAnchorHeld) {
                instrEl.textContent = `✋ Hold down [ ${item.anchorKey} ] with your ${item.anchorHand.toUpperCase()} hand first, then tap [ ${item.tapKey} ]!`;
              } else {
                instrEl.textContent = `Almost! You pressed [ ${letter} ] — tap [ ${item.tapKey} ] with your ${item.tapHand.toUpperCase()} hand!`;
              }
            }
          }
        },

        handleWarmupWindowKeyUp(e) {
          if (!this.warmupActive) return;
          const letter = this.extractKeyLetter(e);
          if (!letter) return;
          const item = this.warmupPlan[this.warmupStepIndex];
          if (item && letter === item.anchorKey) {
            this.warmupAnchorHeld = false;
            this.renderWarmupState();
          }
        },

        handleWarmupCardClick(side) {
          if (!this.warmupActive) return;
          const item = this.warmupPlan[this.warmupStepIndex];
          if (!item) return;

          if (side === item.anchorHand) {
            this.warmupAnchorHeld = !this.warmupAnchorHeld;
            if (this.warmupAnchorHeld) this.playWarmupTone('hold');
            this.renderWarmupState();
          } else if (side === item.tapHand) {
            this.processWarmupTapAttempt();
          }
        },

        processWarmupTapAttempt() {
          const item = this.warmupPlan[this.warmupStepIndex];
          if (!item) return;

          if (!this.warmupAnchorHeld) {
            this.playWarmupTone('remind');
            const anchorCardId = item.anchorHand === 'left' ? 'warmup-left-card' : 'warmup-right-card';
            const anchorCard = document.getElementById(anchorCardId);
            if (anchorCard) {
              anchorCard.classList.remove('shake-warn');
              void anchorCard.offsetWidth;
              anchorCard.classList.add('shake-warn');
            }
            const instrEl = document.getElementById('warmup-instruction');
            if (instrEl) {
              instrEl.className = 'warmup-instruction warn';
              instrEl.textContent = `✋ Hold down [ ${item.anchorKey} ] with your ${item.anchorHand.toUpperCase()} hand first, and keep holding it while your ${item.tapHand.toUpperCase()} hand taps [ ${item.tapKey} ]!`;
            }
            return;
          }

          // Valid bilateral hit!
          const tapCardId = item.tapHand === 'left' ? 'warmup-left-card' : 'warmup-right-card';
          const tapCard = document.getElementById(tapCardId);
          if (tapCard) {
            tapCard.classList.add('pop-hit');
            setTimeout(() => tapCard.classList.remove('pop-hit'), 150);
          }

          this.warmupStepIndex += 1;

          if (this.warmupStepIndex === 10) {
            // Switch from Round 1 (Left holds F, Right taps) to Round 2 (Right holds J, Left taps)
            this.warmupAnchorHeld = false;
            this.playWarmupTone('round');
            this.setCoachFeedback(
              '🔄 Switch Hands!',
              'brilliant',
              'Awesome right-hand tapping, Milo! Now Round 2: Hold down [ J ] with your RIGHT hand and tap with your LEFT hand!',
              'Press and hold [ J ] with your right index finger so your left hand can tap F, D, S, R, E.'
            );
            this.renderWarmupState(true);
            return;
          }

          if (this.warmupStepIndex >= this.warmupPlan.length) {
            this.completeWarmup();
            return;
          }

          this.playWarmupTone('hit', this.warmupStepIndex);
          this.renderWarmupState();
        },

        renderWarmupState(justSwitchedRound = false) {
          const item = this.warmupPlan[this.warmupStepIndex];
          if (!item) return;

          const total = this.warmupPlan.length;
          const pct = Math.round((this.warmupStepIndex / total) * 100);
          document.getElementById('warmup-tap-count').textContent = this.warmupStepIndex;
          document.getElementById('warmup-progress-fill').style.width = `${pct}%`;

          const roundBadge = document.getElementById('warmup-round-badge');
          if (item.round === 1) {
            roundBadge.className = 'warmup-round-badge';
            roundBadge.textContent = 'Round 1 of 2 • Right-Hand Tap';
          } else {
            roundBadge.className = 'warmup-round-badge round-two';
            roundBadge.textContent = 'Round 2 of 2 • Left-Hand Tap';
          }

          const leftCard = document.getElementById('warmup-left-card');
          const rightCard = document.getElementById('warmup-right-card');
          const leftRole = document.getElementById('warmup-left-role');
          const rightRole = document.getElementById('warmup-right-role');
          const leftKey = document.getElementById('warmup-left-key');
          const rightKey = document.getElementById('warmup-right-key');
          const leftStatus = document.getElementById('warmup-left-status');
          const rightStatus = document.getElementById('warmup-right-status');
          const instrEl = document.getElementById('warmup-instruction');

          if (item.round === 1) {
            // Left hand holds [F], Right hand taps [J, K, L, U, I]
            leftKey.textContent = item.anchorKey;
            rightKey.textContent = item.tapKey;

            if (this.warmupAnchorHeld) {
              leftCard.className = 'hand-card anchor-active';
              leftRole.textContent = '✓ HOLDING [ F ]';
              leftStatus.textContent = 'Great! Keep holding [ F ] down!';

              rightCard.className = 'hand-card target-ready';
              rightRole.textContent = '👉 TAP NOW!';
              rightStatus.textContent = `Tap [ ${item.tapKey} ] with your right hand!`;

              instrEl.className = 'warmup-instruction success';
              instrEl.textContent = `✓ Left hand holding [ F ]! Now tap [ ${item.tapKey} ] with your RIGHT hand!`;
            } else {
              leftCard.className = 'hand-card anchor-waiting';
              leftRole.textContent = 'STEP 1: HOLD DOWN';
              leftStatus.textContent = 'Press & hold [ F ] with left hand';

              rightCard.className = 'hand-card target-waiting';
              rightRole.textContent = 'STEP 2: TAP KEY';
              rightStatus.textContent = `Hold [ F ] first, then tap [ ${item.tapKey} ]`;

              instrEl.className = 'warmup-instruction';
              instrEl.textContent = `✋ Hold down [ F ] with your LEFT hand ➔ Tap [ ${item.tapKey} ] with your RIGHT hand!`;
            }
          } else {
            // Round 2: Right hand holds [J], Left hand taps [F, D, S, R, E]
            leftKey.textContent = item.tapKey;
            rightKey.textContent = item.anchorKey;

            if (this.warmupAnchorHeld) {
              rightCard.className = 'hand-card anchor-active';
              rightRole.textContent = '✓ HOLDING [ J ]';
              rightStatus.textContent = 'Great! Keep holding [ J ] down!';

              leftCard.className = 'hand-card target-ready';
              leftRole.textContent = '👉 TAP NOW!';
              leftStatus.textContent = `Tap [ ${item.tapKey} ] with your left hand!`;

              instrEl.className = 'warmup-instruction success';
              instrEl.textContent = `✓ Right hand holding [ J ]! Now tap [ ${item.tapKey} ] with your LEFT hand!`;
            } else {
              rightCard.className = 'hand-card anchor-waiting';
              rightRole.textContent = 'STEP 1: HOLD DOWN';
              rightStatus.textContent = 'Press & hold [ J ] with right hand';

              leftCard.className = 'hand-card target-waiting';
              leftRole.textContent = 'STEP 2: TAP KEY';
              leftStatus.textContent = `Hold [ J ] first, then tap [ ${item.tapKey} ]`;

              instrEl.className = justSwitchedRound ? 'warmup-instruction success' : 'warmup-instruction';
              instrEl.textContent = justSwitchedRound
                ? `🔄 Switch hands! Hold down [ J ] with your RIGHT hand ➔ Tap [ ${item.tapKey} ] with your LEFT hand!`
                : `🤚 Hold down [ J ] with your RIGHT hand ➔ Tap [ ${item.tapKey} ] with your LEFT hand!`;
            }
          }

          // Render sequence dots for current round (10 taps per round)
          const seqRow = document.getElementById('warmup-seq-row');
          const roundStart = item.round === 1 ? 0 : 10;
          const roundSlice = this.warmupPlan.slice(roundStart, roundStart + 10);
          seqRow.innerHTML = roundSlice.map((stepObj, i) => {
            const globalIdx = roundStart + i;
            const cls = globalIdx < this.warmupStepIndex
              ? 'seq-key-dot done'
              : globalIdx === this.warmupStepIndex
                ? 'seq-key-dot current'
                : 'seq-key-dot';
            return `${stepObj.tapKey}`;
          }).join('');
        },

        completeWarmup() {
          this.playWarmupTone('win');
          document.getElementById('warmup-tap-count').textContent = '20';
          document.getElementById('warmup-progress-fill').style.width = '100%';
          const instrEl = document.getElementById('warmup-instruction');
          instrEl.className = 'warmup-instruction success';
          instrEl.textContent = '🎉 Both hands warmed up! +5 💎 Emeralds earned — unlocking Part 1!';

          if (this.currentMission && this.currentMission.levelId) {
            this.markWarmupDoneForMission(this.currentMission.levelId);
          }
          this.awardEmeralds(5, '⚡ Two-Hand Warm-Up Complete! +5 💎');

          setTimeout(() => {
            this.hideWarmupCard();
            this.loadStepIntoEditor(this.currentStepIndex);
            const inputEl = document.getElementById('writing-input');
            if (inputEl) inputEl.focus();
          }, 850);
        },

        /**
         * Checks whether a whitespace token is a genuine English word or number
         * (rejects single-letter key-mashing like 'b', 'n', 'd' and gibberish like 'kjbs', 'dndndd', 'nn').
         */
        isValidEnglishWordToken(rawTok) {
          const clean = String(rawTok || '').replace(/^[^a-zA-Z0-9]+|[^a-zA-Z0-9]+$/g, '');
          if (!clean) return false;
          if (/^\d+(st|nd|rd|th)?$/i.test(clean)) return true;
          if (!/^[a-zA-Z]+(['-][a-zA-Z]+)*$/.test(clean)) return false;
          const lower = clean.toLowerCase().replace(/['-]/g, '');
          if (lower.length === 1) {
            return lower === 'a' || lower === 'i';
          }
          if (lower.length > 20) return false;
          if (/(.)\1\1/.test(lower)) return false;
          if (/^([a-z]{1,3})\1{2,}[a-z]*$/.test(lower)) return false;
          if (/[bcdfghjklmnpqrstvwxz]{5,}/.test(lower)) return false;
          const VOWELLESS_ALLOWED = new Set(['tv', 'mr', 'mrs', 'ms', 'dr', 'st', 'shh', 'hmm', 'hm', 'brr', 'psst', 'nth']);
          if (!/[aeiouy]/.test(lower) && !VOWELLESS_ALLOWED.has(lower)) {
            return false;
          }
          if (/(kj|jb|jv|vf|vk|dbj|hdb|jf|fuhg|ehf|hlh|bsd|sdv|kbs|jbs|dnd|ndn|bjb|fgf|hjh|jkl|sdf|dfg|fgh|ghj|hjk|cvb|vbn|bnm|qwe|wer|ert|rty|tyu|yui|uio|iop|zxc|xcv)/.test(lower)) {
            return false;
          }
          if (/^[bcdfghjklmnpqrstvwxz]{4,}/.test(lower) || /[bcdfghjklmnpqrstvwxz]{4,}$/.test(lower)) {
            if (!/(ngths|mpst|mpts|rlds|rsts|rths|fths|lpts|ncts|rpts|stry|str|spl|spr|scr|shr|thr|chr|phr|sch)/.test(lower)) {
              return false;
            }
          }
          return true;
        },

        /**
         * Counts only valid English words, ignoring standalone punctuation and consecutive duplicate spam.
         */
        countRealWords(text) {
          if (!text || !text.trim()) return 0;
          const rawTokens = text.trim().split(/\s+/).filter(Boolean);
          let count = 0;
          let prevLower = '';
          let repeatRun = 0;
          for (const tok of rawTokens) {
            if (/^[.,!?;:'"()\-—]+$/.test(tok)) continue;
            if (!this.isValidEnglishWordToken(tok)) continue;
            const norm = tok.replace(/^[^a-zA-Z0-9]+|[^a-zA-Z0-9]+$/g, '').toLowerCase();
            if (norm === prevLower) {
              repeatRun += 1;
              if (repeatRun >= 2) continue;
            } else {
              prevLower = norm;
              repeatRun = 1;
            }
            count += 1;
          }
          return count;
        },

        /**
         * Validates step or full-draft text against key-mashing, gibberish, and word-repetition padding.
         */
        validateWritingQuality(text, minWords = 10) {
          const trimmed = (text || '').trim();
          if (!trimmed) {
            return { ok: false, reason: 'short', validWordCount: 0, invalidSample: [] };
          }
          const rawTokens = trimmed.split(/\s+/).filter(Boolean);
          const wordTokens = rawTokens.filter(t => !/^[.,!?;:'"()\-—]+$/.test(t));
          const validWords = [];
          const invalidTokens = [];
          let maxConsecutiveRepeat = 0;
          let currentRepeat = 0;
          let prevNorm = '';
          const freqMap = {};

          for (const tok of wordTokens) {
            if (this.isValidEnglishWordToken(tok)) {
              const norm = tok.replace(/^[^a-zA-Z0-9]+|[^a-zA-Z0-9]+$/g, '').toLowerCase();
              validWords.push(norm);
              freqMap[norm] = (freqMap[norm] || 0) + 1;
              if (norm === prevNorm) {
                currentRepeat += 1;
              } else {
                prevNorm = norm;
                currentRepeat = 1;
              }
              if (currentRepeat > maxConsecutiveRepeat) {
                maxConsecutiveRepeat = currentRepeat;
              }
            } else {
              invalidTokens.push(tok);
            }
          }

          const effectiveValidCount = this.countRealWords(trimmed);

          if (invalidTokens.length >= 3 || (wordTokens.length >= 4 && (validWords.length / wordTokens.length) < 0.72)) {
            const sample = invalidTokens.slice(0, 3).join('", "');
            return {
              ok: false,
              reason: 'gibberish',
              validWordCount: effectiveValidCount,
              invalidSample: invalidTokens.slice(0, 3),
              badge: '🛑 Real Words Only!',
              message: `Whoa there, keyboard ninja! Coach Alex spotted random letters or key-mashing ("${sample}"). Real words only—delete the gibberish and write your own sentences!`,
              hint: `Only real English words count toward your ${minWords}-word goal (repeated letters like "b b b" or "n n n" do not count!).`
            };
          }

          if (validWords.length >= 6) {
            const uniqueCount = Object.keys(freqMap).length;
            const uniqueRatio = uniqueCount / validWords.length;
            const maxFreq = Math.max(...Object.values(freqMap));
            if (maxConsecutiveRepeat >= 3 || (validWords.length >= 8 && uniqueRatio < 0.38) || (validWords.length >= 10 && (maxFreq / validWords.length) > 0.38)) {
              return {
                ok: false,
                reason: 'repetition',
                validWordCount: effectiveValidCount,
                invalidSample: [],
                badge: '🛑 No Word Spamming!',
                message: `Hold on, Milo! Repeating the same word over and over doesn't count as a real sentence. Tell Coach Alex what really happened in your own words!`,
                hint: `Write complete sentences with different words to reach your ${minWords}-word goal.`
              };
            }
          }

          if (effectiveValidCount < Math.max(5, minWords - 3)) {
            return {
              ok: false,
              reason: 'short',
              validWordCount: effectiveValidCount,
              invalidSample: []
            };
          }

          return {
            ok: true,
            reason: 'ok',
            validWordCount: effectiveValidCount,
            invalidSample: []
          };
        },

        sanitizeStoredLogsAndSeedDrafts() {
          try {
            const defaultCleanLogs = [
              {
                timestamp: '2026-10-23 07:42:37',
                missionId: 'L04',
