        saveStepDraftsToStorage() {
          try {
            if (!this.currentMission || !this.currentMission.levelId) return;
            const map = JSON.parse(safeGetStorage(STORAGE_KEYS.STEP_DRAFTS, '{}')) || {};
            map[this.currentMission.levelId] = this.stepDrafts;
            safeSetStorage(STORAGE_KEYS.STEP_DRAFTS, JSON.stringify(map));
          } catch (e) {}
        },

        loadSavedStepDraftsForMission(levelId, stepsCount) {
          try {
            const map = JSON.parse(safeGetStorage(STORAGE_KEYS.STEP_DRAFTS, '{}')) || {};
            const arr = map[levelId];
            if (Array.isArray(arr) && arr.length === stepsCount) {
              // Sanitize each step draft so any old gibberish part is cleared while real parts stay
              return arr.map(partTxt => {
                const trimmed = String(partTxt || '').trim();
                if (!trimmed) return '';
                const check = this.validateWritingQuality(trimmed, 5);
                return (check.reason === 'gibberish' || check.reason === 'repetition') ? '' : trimmed;
              });
            }
          } catch (e) {}
          return new Array(stepsCount).fill('');
        },

        getStepsArray(mission) {
          const list = mission.steps || mission.socraticSteps || mission.workshopMilestones || [];
          if (list.length > 0) {
            return list.map((s, idx) => ({
              shortLabel: `Part ${idx + 1}`,
              question: s.coachQuestion || s.goal || mission.promptScenario,
              hint: s.hint || '',
              minWords: s.minStepWords || s.minParagraphWords || 10
            }));
          }
          return [{
            shortLabel: 'Full Piece',
            question: mission.promptScenario,
            hint: '',
            minWords: mission.minWords || 120
          }];
        },

        renderStepsBar() {
          const steps = this.getStepsArray(this.currentMission);
          const bar = document.getElementById('steps-bar');
          bar.innerHTML = '';
          if (steps.length <= 1) {
            bar.innerHTML = `Full Piece`;
            return;
          }
          steps.forEach((st, idx) => {
            const span = document.createElement('span');
            const stepCheck = this.validateWritingQuality(this.stepDrafts[idx] || '', st.minWords);
            const isDone = stepCheck.ok && stepCheck.validWordCount >= st.minWords;
            span.className = 'step-pill' + (idx === this.currentStepIndex ? ' active' : '') + (isDone ? ' done' : '');
            span.textContent = isDone ? `✓ ${st.shortLabel}` : st.shortLabel;
            span.onclick = () => {
              this.saveCurrentEditorToStep();
              this.loadStepIntoEditor(idx);
            };
            bar.appendChild(span);
          });
        },

        /**
         * Extracts key phrases and details from Milo's previous parts and previous hints
         * so that even without cloud latency, every question and hint builds directly on
         * what Milo actually wrote in earlier steps!
         */
        buildContextualQuestionAndHint(idx) {
          const steps = this.getStepsArray(this.currentMission);
          const baseStep = steps[idx];
          if (idx === 0) {
            return { question: baseStep.question, hint: baseStep.hint };
          }

          if (this.dynamicQuestions[idx] || this.dynamicHints[idx]) {
            return {
              question: this.dynamicQuestions[idx] || baseStep.question,
              hint: this.dynamicHints[idx] || baseStep.hint
            };
          }

          const priorParts = this.stepDrafts.slice(0, idx).map(s => s.trim()).filter(Boolean);
          if (priorParts.length === 0) {
            return { question: baseStep.question, hint: baseStep.hint };
          }

          const allPriorText = priorParts.join(' ');
          const lowerPrior = allPriorText.toLowerCase();
          const latestPriorText = priorParts[priorParts.length - 1];
          const snippet = this.extractKeyPhrase(latestPriorText);
          const lowerBaseQ = baseStep.question.toLowerCase();

          // Smart Anti-Redundancy Check: Detect if Milo ALREADY answered the upcoming question in an earlier part!
                    // Case 0: Cartoons in the Car — check if Milo already mentioned boredom/long rides/quiet driving in Part 1
          if (lowerBaseQ.includes('long car ride') && /(boring|bored|long|traffic|quiet|calm|drive|driving|argue|fighting)/i.test(allPriorText)) {
            return {
              question: `👉 Part ${idx + 1}: You already mentioned how car rides can feel ${RegExp.$1.toLowerCase()}! What kind of cartoons would you and Ollie watch together in the back seat, and how does sharing a show help the person driving?`,
              hint: `Describe how watching a show together keeps the back seat peaceful and happy so Mum or Dad can focus on the road!`
            };
          }
          if (lowerBaseQ.includes('parents sometimes worry') && /(eyes|dizzy|sick|minute|limit|rule|promise|long trip)/i.test(allPriorText)) {
            return {
              question: `👉 Part ${idx + 1}: Building on what you said about "${snippet}", how will you and Ollie prove to Mum and Dad that you can turn the screen off immediately without complaining when the car parks?`,
              hint: `Explain the exact deal or rule you and Ollie will follow so Mum and Dad never have to remind you twice!`
            };
          }

          // Case 1: Upcoming step asks about favourite food/dish, but Milo already named a specific food/dish in Part 1
          const foodMatch = allPriorText.match(/\b(cucumber[^.,!]*|sushi|ramen|noodles|pizza|burger|dumplings|dim sum|pasta|steak|curry|rice|chicken|ice cream|pancakes)\b/i);
          if ((lowerBaseQ.includes('best food') || lowerBaseQ.includes('best dish') || lowerBaseQ.includes('what to eat')) && foodMatch) {
            const dish = foodMatch[0];
            return {
              question: `👉 Part ${idx + 1}: You already mentioned loving ${dish}! When it arrives at your table, what does the restaurant smell or look like, and what makes eating ${dish} there so good?`,
              hint: `Describe the smell at the table, how the food arrives (like on a sushi train or sizzling plate), or how ${dish} tastes!`
            };
          }

          // Case 2: Upcoming step asks about the first spell/game, but Milo already named a spell in Part 1
          const spellMatch = allPriorText.match(/\b(avada\s*k[ae]davra|expelliarmus|wingardium\s*leviosa|lumos|expecto\s*patronum|alohomora|spell)\b/i);
          if (lowerBaseQ.includes('first spell') && spellMatch) {
            return {
              question: `👉 Part ${idx + 1}: Since you already mentioned ${spellMatch[0]}, how did you and Ollie act out your wizard duel or magical adventure around the house?`,
              hint: `Describe where you and Ollie stood in the house and how you waved your wands or dodged each other's spells!`
            };
          }

          // Case 3: Upcoming step asks about convincing the family / what others think, and Milo already mentioned brother/Ollie/mom/dad
          if (lowerBaseQ.includes('convincing') || lowerBaseQ.includes('someone else in the family')) {
            const placeMatch = allPriorText.match(/\b(Genki\s*Sushi|[A-Z][a-z]+\s+(?:Sushi|Restaurant|Cafe|Kitchen|Pizza|House))\b/);
            const placeName = placeMatch ? placeMatch[0] : 'your chosen spot';
            return {
              question: `👉 Part ${idx + 1}: You and Ollie love ${placeName}, but what if Mum or Dad wants to eat something different? How does going to ${placeName} work out for the whole family?`,
              hint: `Explain what you and Ollie get to choose there, or why Mum and Dad should still take you!`
            };
          }

          // Case 4: Closing / Final Part — weave in the main details from Parts 1..N-1
          if (idx === steps.length - 1 && priorParts.length >= 2) {
            return {
              question: `👉 Final Part (${idx + 1} of ${steps.length}): Building on everything you wrote so far ("${snippet}"), ${baseStep.question.replace(/^👉\s*Part\s*\d+[^:]*:\s*/i, '')}`,
              hint: `Tie together your earlier points into a memorable final sentence or two!`
            };
          }

          return {
            question: `👉 Part ${idx + 1} (building on "${snippet}"): ${baseStep.question.replace(/^👉\s*Part\s*\d+[^:]*:\s*/i, '')}`,
            hint: `Connect directly to "${snippet}"! ${baseStep.hint}`
          };
        },

        extractKeyPhrase(text) {
          if (!text) return '';
          const cleaned = text.replace(/["']/g, '').trim();
          const sentences = cleaned.split(/(?<=[.!?])\s+/).filter(Boolean);
          const lastSent = (sentences[sentences.length - 1] || cleaned).replace(/[.!?]+$/, '').trim();
          const words = lastSent.split(/\s+/);
          if (words.length <= 9) return lastSent;
          return words.slice(0, 9).join(' ') + '...';
        },

        loadStepIntoEditor(idx) {
          const steps = this.getStepsArray(this.currentMission);
          this.currentStepIndex = idx;
          const st = steps[idx];

          const contextual = this.buildContextualQuestionAndHint(idx);

          const praiseBanner = document.getElementById('last-step-feedback');
          if (idx > 0 && this.lastPraiseBannerText) {
            praiseBanner.innerHTML = this.lastPraiseBannerText;
            praiseBanner.classList.add('visible');
          } else {
            praiseBanner.classList.remove('visible');
          }

          this.setCoachFeedback("⭐ Let's Write", 'great', contextual.question, '');
          document.getElementById('step-word-goal').textContent = st.minWords;

          const btnSubmit = document.getElementById('btn-submit-step');
          btnSubmit.textContent = (idx < steps.length - 1) ? '✅ Next Part' : '✅ Save Final Part';

          const inputEl = document.getElementById('writing-input');
          inputEl.value = this.stepDrafts[idx] || '';
          this.renderStepsBar();
          this.handleInputUpdate();
        },

        saveCurrentEditorToStep() {
          const val = document.getElementById('writing-input').value;
          this.stepDrafts[this.currentStepIndex] = val;
          this.saveStepDraftsToStorage();
        },

        handleKeyDown(e) {
          const now = Date.now();
          if (!this.typingStartTime) this.typingStartTime = now;
          if (this.lastKeystrokeTime && (now - this.lastKeystrokeTime) < 4000) {
            this.activeTypingSeconds += (now - this.lastKeystrokeTime) / 1000;
          }
          this.lastKeystrokeTime = now;
        },

        handleInputUpdate() {
          this.saveCurrentEditorToStep();
          const currentText = document.getElementById('writing-input').value.trim();
          const stepWords = this.countRealWords(currentText);

          const fullDraft = this.getCompiledDraftText();
          const totalWords = this.countRealWords(fullDraft);

          document.getElementById('step-word-count').textContent = stepWords;
          document.getElementById('total-word-count').textContent = totalWords;

          const elapsedMin = Math.max(0.15, this.activeTypingSeconds / 60);
          if (totalWords > 2) {
            this.currentWpm = Math.min(95, Math.round(totalWords / elapsedMin));
            document.getElementById('hud-wpm').textContent = this.currentWpm;
          }

          this.renderCompiledScroll();
        },

        getCompiledDraftText() {
          return this.stepDrafts.map(s => s.trim()).filter(Boolean).join('\n\n');
        },

        getStorySoFarUpTo(maxIdx) {
          return this.stepDrafts
            .slice(0, maxIdx)
            .map((s, i) => s.trim() ? `Part ${i + 1}: "${s.trim()}"` : '')
            .filter(Boolean)
            .join('\n');
        },

        renderCompiledScroll() {
          const box = document.getElementById('compiled-scroll');
          const steps = this.getStepsArray(this.currentMission);
          const nonEmpty = this.stepDrafts.some(s => s.trim().length > 0);
          if (!nonEmpty) {
            box.innerHTML = `
Your finished parts will appear here as you write.`;
            return;
          }

          box.innerHTML = '';
          steps.forEach((st, idx) => {
            const txt = (this.stepDrafts[idx] || '').trim();
            if (!txt) return;
            const part = document.createElement('div');
            part.className = 'compiled-part';
            part.innerHTML = `
${this.escapeHtml(txt)}`;
            box.appendChild(part);
          });
        },

        async submitCurrentStep() {
          this.saveCurrentEditorToStep();
          const steps = this.getStepsArray(this.currentMission);
          const st = steps[this.currentStepIndex];
          const text = (this.stepDrafts[this.currentStepIndex] || '').trim();
          const quality = this.validateWritingQuality(text, st.minWords);
          const wordCount = quality.validWordCount;

          if (!quality.ok) {
            const contextual = this.buildContextualQuestionAndHint(this.currentStepIndex);
            if (quality.reason === 'gibberish' || quality.reason === 'repetition') {
              this.setCoachFeedback(
                quality.badge,
                'inaccuracy',
                quality.message,
                quality.hint
              );
              this.showToast('🛑 Please use real English words and sentences!');
              return;
            }
            this.setCoachFeedback(
              '🔧 Add a Little More',
              'inaccuracy',
              `Nice start, Milo! You have ${wordCount} real words so far—try adding one more detail to reach ${st.minWords} words.`,
              contextual.hint
            );
            return;
          }

          const btnSubmit = document.getElementById('btn-submit-step');
          const origBtnText = btnSubmit.textContent;
          btnSubmit.textContent = '⏳ Coach Alex is reading...';
          btnSubmit.disabled = true;

          const analysis = this.analyzeSentenceHeuristically(text, this.currentStepIndex);
          const nextIdx = this.currentStepIndex + 1;
          const nextStepObj = (nextIdx < steps.length) ? steps[nextIdx] : null;

          const liveFeedback = await this.fetchLiveCoachTurn(text, st, nextStepObj);
          btnSubmit.disabled = false;
          btnSubmit.textContent = origBtnText;

          let finalBadge = analysis.badge;
          let finalBadgeClass = analysis.badgeClass;
          let finalPraise = analysis.praise;

          if (liveFeedback) {
            finalBadge = liveFeedback.moveBadge || analysis.badge;
            finalBadgeClass = (finalBadge || '').includes('Brilliant') ? 'brilliant' :
                              (finalBadge || '').includes('Fix') || (finalBadge || '').includes('Inaccuracy') ? 'inaccuracy' : 'great';
            finalPraise = liveFeedback.coachPraise || analysis.praise;
            if (nextStepObj && liveFeedback.dynamicNextQuestion) {
              this.dynamicQuestions[nextIdx] = liveFeedback.dynamicNextQuestion;
            }
            if (nextStepObj && liveFeedback.dynamicNextHint) {
              this.dynamicHints[nextIdx] = liveFeedback.dynamicNextHint;
            }
          }

          this.coachHistory.push({
            stepIndex: this.currentStepIndex + 1,
            studentText: text,
            praiseGiven: finalPraise,
            hintGiven: (liveFeedback && liveFeedback.dynamicNextHint) ? liveFeedback.dynamicNextHint : analysis.hint
          });

          this.awardEmeralds(5, `✅ Part ${this.currentStepIndex + 1} saved! +5 💎`);

          const fixNote = analysis.hint ? ` (${this.escapeHtml(analysis.hint)})` : '';
          this.lastPraiseBannerText = `${this.escapeHtml(finalBadge)} on Part ${this.currentStepIndex + 1}: ${this.escapeHtml(finalPraise)}${fixNote}`;

          this.setCoachFeedback(finalBadge, finalBadgeClass, finalPraise, analysis.hint);

          if (this.currentStepIndex < steps.length - 1) {
            clearTimeout(this._stepAdvanceTimer);
            this._stepAdvanceTimer = setTimeout(() => {
              this.loadStepIntoEditor(this.currentStepIndex + 1);
            }, 4800);
          } else {
            this.runGameReview();
          }
        },

        async askHint() {
          this.saveCurrentEditorToStep();
          const text = document.getElementById('writing-input').value.trim();
          const contextual = this.buildContextualQuestionAndHint(this.currentStepIndex);

          const btnHint = document.getElementById('btn-hint');
          btnHint.textContent = '⏳ Thinking...';

          const liveHint = await this.fetchLiveContextualHint(text, contextual.question);
          btnHint.textContent = '💡 Hint';

          if (liveHint && liveHint.contextualHint) {
            this.dynamicHints[this.currentStepIndex] = liveHint.contextualHint;
            this.coachHistory.push({
              stepIndex: this.currentStepIndex + 1,
              studentText: text,
              hintGiven: liveHint.contextualHint
            });
            this.setCoachFeedback('💡 Coach Hint', 'great', contextual.question, liveHint.contextualHint);
            return;
          }

          if (!text) {
            this.coachHistory.push({
              stepIndex: this.currentStepIndex + 1,
              studentText: '',
              hintGiven: contextual.hint
            });
            this.setCoachFeedback('💡 Coach Hint', 'great', contextual.question, contextual.hint);
            return;
          }

          const analysis = this.analyzeSentenceHeuristically(text, this.currentStepIndex);
          const combinedHint = `${analysis.praise} ${analysis.hint}`;
          this.coachHistory.push({
            stepIndex: this.currentStepIndex + 1,
            studentText: text,
            hintGiven: combinedHint
          });
          this.setCoachFeedback(analysis.badge, analysis.badgeClass, contextual.question, combinedHint);
        },

        /**
         * Context-conscious, varied feedback analyzer (never repeats "vivid, well-explained part"!).
         */
        analyzeSentenceHeuristically(text, stepIdx = 0) {
          const words = text.split(/\s+/).filter(Boolean);
          const lower = text.toLowerCase();
          const snippet = this.extractKeyPhrase(text);

          // 1. Check all common misspellings (collect up to 2 so Milo gets specific, helpful feedback)
          const foundSlips = [];
          for (const [wrong, right] of Object.entries(COMMON_MISSPELLINGS)) {
            const regex = new RegExp(`\\b${wrong}\\b`, 'i');
            if (regex.test(text)) {
              foundSlips.push({ wrong, right });
            }
          }
          if (/\btake it of\b/i.test(text)) {
            foundSlips.push({ wrong: 'take it of', right: 'take it off' });
          }

          // 2. Build content-specific praise based on what Milo actually wrote in this sentence/part!
          let contentPraise = '';
          if (/because|becuase|since|so that/i.test(text)) {
            contentPraise = `I love how you explained the reason behind your choice ("${snippet}")!`;
          } else if (/smell|taste|sound|look|feel|dipped|crispy|warm|sweet|savory/i.test(text)) {
            contentPraise = `Bringing in senses like smell and taste in "${snippet}" makes the reader feel right there at the table!`;
          } else if (/ollie|brother|mom|mum|dad|family|friend/i.test(text)) {
            contentPraise = `Including your family in "${snippet}" makes your writing personal and fun to read!`;
          } else if (/anyways|actually|however|although|first|next|finally/i.test(text)) {
            contentPraise = `Great conversational voice in "${snippet}"—your transition connects your thoughts smoothly!`;
          } else {
            const variedPraises = [
              `Great job naming specific details in "${snippet}"!`,
              `Your point in "${snippet}" comes across clearly and naturally!`,
              `Nice storytelling touch in "${snippet}"—it sets up the scene really well!`,
              `I like the specific example you chose in "${snippet}"!`
            ];
            contentPraise = variedPraises[(stepIdx + words.length) % variedPraises.length];
          }

          // 3. If there was a spelling slip, combine the warm content praise with the exact spelling fix!
          if (foundSlips.length > 0) {
            const slipDesc = foundSlips.slice(0, 2).map(s => `"${s.wrong}" ➔ "${s.right}"`).join(' and ');
            return {
              badge: '🔧 Quick Fix',
              badgeClass: 'inaccuracy',
              praise: contentPraise,
              hint: `Quick spelling check: try fixing ${slipDesc}.`
            };
          }

          // 4. Check if sentence starts with a lowercase letter
          if (/^[a-z]/.test(text.trim())) {
            const firstW = words[0];
            const capW = firstW.charAt(0).toUpperCase() + firstW.slice(1);
            return {
              badge: '🔧 Quick Fix',
              badgeClass: 'inaccuracy',
              praise: contentPraise,
              hint: `Remember to start your sentence with a capital letter ("${firstW}" ➔ "${capW}").`
            };
          }

          // 5. Check weak basic words
          for (const [weak, upgrades] of Object.entries(WEAK_WORDS_MAP)) {
            const regex = new RegExp(`\\b${weak}\\b`, 'i');
            if (regex.test(text)) {
              return {
                badge: '⭐ Great!',
                badgeClass: 'great',
                praise: contentPraise,
                hint: `Bonus tip: you can make "${weak}" even stronger by swapping it for "${upgrades[0]}" or "${upgrades[1]}".`
              };
            }
          }

          if (words.length >= 14) {
            return {
              badge: '💎 Brilliant!!',
              badgeClass: 'brilliant',
              praise: contentPraise,
              hint: `Spot-on spelling and detail (${words.length} words)!`
            };
          }

          return {
            badge: '⭐ Great!',
            badgeClass: 'great',
            praise: contentPraise,
            hint: `Add one more detail or reason to turn this into a 💎 Brilliant!! move.`
          };
        },

        runGameReview() {
          this.saveCurrentEditorToStep();
          const steps = this.getStepsArray(this.currentMission);
          for (let i = 0; i < steps.length; i++) {
            const partTxt = (this.stepDrafts[i] || '').trim();
            const partCheck = this.validateWritingQuality(partTxt, steps[i].minWords);
            if (!partCheck.ok) {
              this.loadStepIntoEditor(i);
              if (partCheck.reason === 'gibberish' || partCheck.reason === 'repetition') {
                this.setCoachFeedback(partCheck.badge, 'inaccuracy', partCheck.message, partCheck.hint);
                this.showToast(`🛑 Please fix ${steps[i].shortLabel} with real words first!`);
              } else {
                const contextual = this.buildContextualQuestionAndHint(i);
                this.setCoachFeedback(
                  '🔧 Finish All Parts First',
                  'inaccuracy',
                  `${steps[i].shortLabel} has ${partCheck.validWordCount} real words so far (goal: ${steps[i].minWords} words). Finish this part before checking your full piece!`,
                  contextual.hint
                );
                this.showToast(`✏️ Please finish ${steps[i].shortLabel} (${partCheck.validWordCount}/${steps[i].minWords} words) first!`);
              }
              return;
            }
          }

          const fullDraft = this.getCompiledDraftText();
          const fullCheck = this.validateWritingQuality(fullDraft, this.currentMission.minWords || 45);
          if (!fullCheck.ok) {
            if (fullCheck.reason === 'gibberish' || fullCheck.reason === 'repetition') {
              this.setCoachFeedback(fullCheck.badge, 'inaccuracy', fullCheck.message, fullCheck.hint);
            }
            this.showToast('🛑 Please write complete sentences using real English words!');
            return;
          }

          const rawSentences = fullDraft
            .split(/(?<=[.!?])\s+|\n+/)
            .map(s => s.trim())
            .filter(s => s.length > 2);

          let brilliantCount = 0;
          let greatCount = 0;
          let inaccuracyCount = 0;
          const annotations = [];
          const retryCandidates = [];

          rawSentences.forEach((sent, sIdx) => {
            const res = this.analyzeSentenceHeuristically(sent, sIdx);
            if (res.badgeClass === 'brilliant') brilliantCount++;
            else if (res.badgeClass === 'inaccuracy') {
              inaccuracyCount++;
              retryCandidates.push({
                original: sent,
                prompt: res.hint
              });
            } else {
              greatCount++;
            }
            annotations.push({ sentence: sent, ...res });
          });

          document.getElementById('rev-brilliant-count').textContent = brilliantCount;
          document.getElementById('rev-great-count').textContent = greatCount;
          document.getElementById('rev-inaccuracy-count').textContent = inaccuracyCount;

          document.getElementById('review-coach-summary').textContent =
            `Awesome work finishing "${this.currentMission.title}", Milo! You wrote ${fullDraft.split(/\s+/).length} words at ${this.currentWpm || 18} WPM. Here is how each sentence went:`;

          const listEl = document.getElementById('sentence-review-list');
          listEl.innerHTML = '';
          annotations.forEach(item => {
            const div = document.createElement('div');
            div.className = 'sentence-item';
            div.innerHTML = `
              ${item.badge}
              "${this.escapeHtml(item.sentence)}"

${this.escapeHtml(item.praise)} ${this.escapeHtml(item.hint)}
            `;
            listEl.appendChild(div);
          });

          const retryInput = document.getElementById('retry-input');
          const retryPromptEl = document.getElementById('retry-prompt-text');
          if (retryCandidates.length > 0) {
            const target = retryCandidates[0];
            retryPromptEl.innerHTML = `Sentence to Polish: "${this.escapeHtml(target.original)}"
Coach Tip: ${this.escapeHtml(target.prompt)}`;
            retryInput.value = target.original;
          } else {
            const firstSent = rawSentences[0] || '';
            retryPromptEl.innerHTML = `Zero spelling slips! Add one extra descriptive word to this sentence for +10 💎:
"${this.escapeHtml(firstSent)}"`;
            retryInput.value = firstSent;
          }

          document.getElementById('review-panel').classList.add('visible');
          document.getElementById('review-panel').scrollIntoView({ behavior: 'smooth' });

          this.recordSilentParentAnalytics(fullDraft, brilliantCount, greatCount, inaccuracyCount);
        },

        submitRetryChallenge() {
          if (this.retryCompletedForMission) {
            this.showToast('✅ Bonus already claimed for this level!');
            return;
          }
          const val = document.getElementById('retry-input').value.trim();
          const retryCheck = this.validateWritingQuality(val, 5);
          if (!retryCheck.ok) {
            this.showToast('⚠️ Please type out the full sentence using real words!');
            return;
          }
          this.retryCompletedForMission = true;
          this.awardEmeralds(10, '🏆 +10 Bonus Emeralds!');
        },

        advanceToNextLevel() {
          if (this.currentMissionIndex < this.missions.length - 1) {
            this.currentMissionIndex += 1;
            safeSetStorage(STORAGE_KEYS.CURRENT_LEVEL_IDX, String(this.currentMissionIndex));
            document.getElementById('level-select').value = this.currentMissionIndex;
            this.selectMission(this.missions[this.currentMissionIndex]);
            window.scrollTo({ top: 0, behavior: 'smooth' });
            this.showToast(`🚀 ${this.missions[this.currentMissionIndex].title}`);
          } else {
            this.showToast(`🎉 All 9 levels completed!`);
          }
        },

        recordSilentParentAnalytics(fullDraft, brilliantCount, greatCount, inaccuracyCount) {
          const words = this.countRealWords(fullDraft);
          const goal = this.currentMission.minWords || 45;

          const contentScore = Math.min(9.5, Math.max(5.5, Number((6.5 + Math.min(2.0, (words / goal) * 1.5) + brilliantCount * 0.3).toFixed(1))));
          const languageScore = Math.min(9.5, Math.max(5.5, Number((6.2 + brilliantCount * 0.5 + greatCount * 0.2 - inaccuracyCount * 0.2).toFixed(1))));
          const spellingScore = Math.min(9.5, Math.max(5.5, Number((8.5 - inaccuracyCount * 0.5).toFixed(1))));
          const total30 = Number((contentScore + languageScore + spellingScore).toFixed(1));
          const band = total30 >= 24 ? 'ISA Level 5 (Advanced Upper Elementary)' :
                       total30 >= 20 ? 'ISA Level 4 (Proficient Upper Elementary)' :
                                       'ISA Level 3 (Developing Upper Elementary)';

          const entry = {
            timestamp: new Date().toISOString().slice(0, 16).replace('T', ' '),
            missionId: this.currentMission.levelId,
            missionTitle: this.currentMission.title,
            genre: this.currentMission.genre,
            modeLabel: this.currentMission.genreBadge,
            wordCount: words,
            wpm: this.currentWpm || 22,
            durationSec: Math.round(this.activeTypingSeconds || 120),
            emeraldsEarned: this.currentMission.emeraldReward || 15,
            brilliantCount,
            greatCount,
            inaccuracyCount,
            retriesCompleted: this.retryCompletedForMission ? 1 : 0,
            isaContent10: contentScore,
            isaLanguage10: languageScore,
            isaSpelling10: spellingScore,
            isaTotal30: total30,
            isaBand: band,
            compiledDraft: fullDraft
          };

          const existing = JSON.parse(safeGetStorage(STORAGE_KEYS.PARENT_LOGS, '[]'));
          existing.unshift(entry);
          safeSetStorage(STORAGE_KEYS.PARENT_LOGS, JSON.stringify(existing.slice(0, 50)));

          const webAppUrl = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL);
          if (webAppUrl) {
            fetch(webAppUrl, {
              method: 'POST',
              mode: 'no-cors',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'log_session', ...entry })
            }).catch(() => {});
          }
        },

        /**
         * Uses JSONP fallback on iPad Safari if POST redirect is blocked by WebKit!
         */
        async fetchLiveCoachTurn(studentText, stepObj, nextStepObj) {
          const webAppUrl = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL);
          const apiKey = safeGetStorage(STORAGE_KEYS.GEMINI_KEY, '');
          if (!webAppUrl) return null;

          const reqPayload = {
            action: 'socratic_turn',
            gcpProjectId: (safeGetStorage(STORAGE_KEYS.GCP_PROJECT, '') || DEFAULT_GCP_PROJECT),
            gcpLocation: safeGetStorage(STORAGE_KEYS.GCP_LOCATION, 'us-central1'),
            apiKey,
            genre: this.currentMission.genre,
            promptScenario: this.currentMission.promptScenario,
            storySoFar: this.getStorySoFarUpTo(this.currentStepIndex + 1),
            previousHistory: this.coachHistory,
            stepGoal: stepObj.question,
            studentText,
            nextStepGoal: nextStepObj ? nextStepObj.question : '',
            nextStepBaseHint: nextStepObj ? nextStepObj.hint : ''
          };

          try {
            const resp = await fetch(webAppUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'text/plain;charset=utf-8' },
              body: JSON.stringify(reqPayload)
            });
            const data = await resp.json();
            if (data && data.status === 'ok' && data.coachResponse) {
              return data.coachResponse;
            }
          } catch (e) {
            // Fallback to JSONP GET so iPad Safari 302 redirect never blocks the AI Coach!
            const jsonpRes = await this.callActionViaJsonp(webAppUrl, 'socratic_turn', reqPayload);
            if (jsonpRes && jsonpRes.status === 'ok' && jsonpRes.coachResponse) {
              return jsonpRes.coachResponse;
            }
          }
          return null;
        },

        async fetchLiveContextualHint(studentText, currentQuestion) {
          const webAppUrl = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL);
          const apiKey = safeGetStorage(STORAGE_KEYS.GEMINI_KEY, '');
          if (!webAppUrl) return null;

          const reqPayload = {
            action: 'contextual_hint',
            gcpProjectId: (safeGetStorage(STORAGE_KEYS.GCP_PROJECT, '') || DEFAULT_GCP_PROJECT),
            gcpLocation: safeGetStorage(STORAGE_KEYS.GCP_LOCATION, 'us-central1'),
            apiKey,
            promptScenario: this.currentMission.promptScenario,
            storySoFar: this.getStorySoFarUpTo(this.currentStepIndex),
            previousHistory: this.coachHistory,
            stepGoal: currentQuestion,
            studentText
          };

          try {
            const resp = await fetch(webAppUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'text/plain;charset=utf-8' },
              body: JSON.stringify(reqPayload)
            });
            const data = await resp.json();
            if (data && data.status === 'ok' && data.hintResponse) {
              return data.hintResponse;
            }
          } catch (e) {
            const jsonpRes = await this.callActionViaJsonp(webAppUrl, 'contextual_hint', reqPayload);
            if (jsonpRes && jsonpRes.status === 'ok' && jsonpRes.hintResponse) {
              return jsonpRes.hintResponse;
            }
          }
          return null;
        },

        callActionViaJsonp(webAppUrl, actionName, payloadObj) {
          return new Promise((resolve) => {
            const cbName = '__miloActCb_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
            const sep = webAppUrl.includes('?') ? '&' : '?';
            const script = document.createElement('script');
            const timer = setTimeout(() => {
              if (window[cbName]) delete window[cbName];
              script.remove();
              resolve(null);
            }, 6500);
            window[cbName] = (res) => {
              clearTimeout(timer);
              delete window[cbName];
              script.remove();
              resolve(res);
            };
            script.onerror = () => {
              clearTimeout(timer);
              delete window[cbName];
              script.remove();
              resolve(null);
            };
            script.src = `${webAppUrl}${sep}action=${encodeURIComponent(actionName)}&payload=${encodeURIComponent(JSON.stringify(payloadObj))}&callback=${cbName}&t=${Date.now()}`;
            document.body.appendChild(script);
          });
        },

        syncCloudMissions(manual = false) {
          const webAppUrl = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL).trim();
          if (!webAppUrl) {
            if (manual) this.showToast('⚠️ Tap ☁️ first to paste your Apps Script Web App URL!');
            return;
          }
          if (manual) this.showToast('🔄 Syncing latest questions from Google Drive...');
          const sep = webAppUrl.includes('?') ? '&' : '?';
          const url = `${webAppUrl}${sep}child=milo&t=${Date.now()}`;

          fetch(url, { redirect: 'follow' })
            .then(r => r.json())
            .then(res => {
              if (res && res.status === 'ok' && res.data && res.data.missions) {
                this.data = res.data;
                this.loadMissions(res.data.missions);
                this.showToast('☁️ Loaded latest questions from Google Drive!');
              } else {
                this.syncViaJsonp(webAppUrl, manual);
              }
            })
            .catch(() => {
              // Resilient JSONP fallback for iPad/iPhone Safari cross-origin redirects
              this.syncViaJsonp(webAppUrl, manual);
            });
        },

        syncViaJsonp(webAppUrl, manual) {
          const cbName = '__miloJsonpCb_' + Date.now();
          const sep = webAppUrl.includes('?') ? '&' : '?';
          const script = document.createElement('script');
          window[cbName] = (res) => {
            delete window[cbName];
            script.remove();
            if (res && res.status === 'ok' && res.data && res.data.missions) {
              this.data = res.data;
              this.loadMissions(res.data.missions);
              this.showToast('☁️ Loaded latest questions from Google Drive!');
            } else if (manual) {
              this.showToast('⚠️ Connected to script, but no questions file found.');
            }
          };
          script.onerror = () => {
            delete window[cbName];
            script.remove();
            if (manual) this.showToast('⚠️ Could not reach Web App URL. Check ☁️ settings.');
          };
          script.src = `${webAppUrl}${sep}child=milo&callback=${cbName}&t=${Date.now()}`;
          document.body.appendChild(script);
        },

        setCoachFeedback(badgeText, badgeClass, message, hint) {
          const badgeEl = document.getElementById('coach-move-badge');
          badgeEl.className = `move-badge ${badgeClass}`;
          badgeEl.textContent = badgeText;
          document.getElementById('coach-message').textContent = message;

          const hintEl = document.getElementById('coach-hint');
          if (hint && hint.trim().length > 0) {
            hintEl.textContent = `💡 ${hint}`;
            hintEl.classList.add('visible');
          } else {
            hintEl.textContent = '';
            hintEl.classList.remove('visible');
          }
        },

        awardEmeralds(amount, reasonText) {
          this.emeralds += amount;
          safeSetStorage(STORAGE_KEYS.EMERALDS, String(this.emeralds));
          this.updateEmeraldHud();
          if (reasonText) this.showToast(reasonText);
        },

        updateEmeraldHud() {
          document.getElementById('hud-emeralds').textContent = this.emeralds;
        },

        speakCoachPrompt() {
          const msg = document.getElementById('coach-message').textContent;
          this.speakText(msg);
        },

        speakCompiledDraft() {
          const txt = this.getCompiledDraftText();
          if (!txt) {
            this.showToast('Write a sentence first so I can read it aloud!');
            return;
          }
          this.speakText(txt);
        },

        speakText(text) {
          if (!('speechSynthesis' in window)) return;
          window.speechSynthesis.cancel();
          const utter = new SpeechSynthesisUtterance(text);
          utter.lang = 'en-GB';
          utter.rate = 0.96;
          window.speechSynthesis.speak(utter);
        },

        openSettingsModal() {
          document.getElementById('input-webapp-url').value = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL);
          document.getElementById('input-gcp-project').value = (safeGetStorage(STORAGE_KEYS.GCP_PROJECT, '') || DEFAULT_GCP_PROJECT);
          document.getElementById('input-gcp-location').value = safeGetStorage(STORAGE_KEYS.GCP_LOCATION, 'us-central1');
          document.getElementById('input-gemini-key').value = safeGetStorage(STORAGE_KEYS.GEMINI_KEY, '');
          this.renderParentLogsTable();
          document.getElementById('settings-modal').classList.add('open');
        },

        closeSettingsModal() {
          document.getElementById('settings-modal').classList.remove('open');
        },

        saveCloudSettings() {
          const url = document.getElementById('input-webapp-url').value.trim();
          const proj = document.getElementById('input-gcp-project').value.trim();
          const loc = document.getElementById('input-gcp-location').value.trim() || 'us-central1';
          const key = document.getElementById('input-gemini-key').value.trim();
          safeSetStorage(STORAGE_KEYS.WEBAPP_URL, url);
          safeSetStorage(STORAGE_KEYS.GCP_PROJECT, proj);
          safeSetStorage(STORAGE_KEYS.GCP_LOCATION, loc);
          safeSetStorage(STORAGE_KEYS.GEMINI_KEY, key);

          if (url) {
            fetch(url, {
              method: 'POST',
              mode: 'no-cors',
              body: JSON.stringify({ action: 'save_cloud_config', gcpProjectId: proj, gcpLocation: loc, apiKey: key })
            }).catch(() => {});
          }
          this.showToast('☁️ Cloud Settings Saved!');
          this.syncCloudMissions();
          this.closeSettingsModal();
        },

        renderParentLogsTable() {
          const tbody = document.getElementById('parent-log-tbody');
          const logs = JSON.parse(safeGetStorage(STORAGE_KEYS.PARENT_LOGS, '[]'));
          if (logs.length === 0) {
            tbody.innerHTML = `
No completed sessions recorded on this device yet.`;
            return;
          }
          tbody.innerHTML = logs.map(l => `


              ${l.timestamp}
              ${this.escapeHtml(l.missionTitle)}
              ${l.wordCount}w / ${l.wpm} WPM
              ${l.isaContent10}
              ${l.isaLanguage10}
              ${l.isaSpelling10}
              ${l.isaTotal30} / 30
              ${l.isaBand}

          `).join('');
        },

        resetAllProgress() {
          safeSetStorage(STORAGE_KEYS.EMERALDS, '20');
          safeSetStorage(STORAGE_KEYS.CURRENT_LEVEL_IDX, '0');
          safeSetStorage(STORAGE_KEYS.PARENT_LOGS, '[]');
          safeSetStorage(STORAGE_KEYS.WARMUP_DONE, '{}');
          safeSetStorage(STORAGE_KEYS.STEP_DRAFTS, '{}');
          this.emeralds = 20;
          this.updateEmeraldHud();
          this.currentMissionIndex = 0;
          document.getElementById('level-select').value = 0;
          if (this.missions[0]) this.selectMission(this.missions[0]);
          this.renderParentLogsTable();
          const webAppUrl = (safeGetStorage(STORAGE_KEYS.WEBAPP_URL, '') || DEFAULT_WEBAPP_URL);
          if (webAppUrl) {
            fetch(webAppUrl, {
              method: 'POST',
              mode: 'no-cors',
              body: JSON.stringify({ action: 'clear_records' })
            }).catch(() => {});
          }
          this.showToast('✨ Progress and logs cleared! Ready for a fresh start at Level 1.');
          this.closeSettingsModal();
        },

        exportParentCsv() {
          const logs = JSON.parse(safeGetStorage(STORAGE_KEYS.PARENT_LOGS, '[]'));
          const headers = ['Timestamp','Level_ID','Title','Genre','Word_Count','WPM','Content_10','Language_10','Spelling_10','ISA_Total_30','ISA_Band','Compiled_Draft'];
          const rows = logs.map(l => [
            l.timestamp, l.missionId, `"${(l.missionTitle||'').replace(/"/g,'""')}"`, l.genre,
            l.wordCount, l.wpm, l.isaContent10, l.isaLanguage10, l.isaSpelling10, l.isaTotal30,
            `"${l.isaBand}"`, `"${(l.compiledDraft||'').replace(/"/g,'""')}"`
          ].join(','));
          const csv = [headers.join(','), ...rows].join('\n');
          const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'Milo_ISA_Writing_Report.csv';
          a.click();
        },

        showToast(msg) {
          const el = document.getElementById('toast-box');
          el.textContent = msg;
          el.classList.add('show');
          clearTimeout(this._toastTimer);
          this._toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
        },

        escapeHtml(str) {
          return String(str || '')
            .replace(/&/g, '&')
            .replace(//g, '>')
            .replace(/"/g, '"');
        }
      };

      window.GameEngine = GameEngine;
      document.addEventListener('DOMContentLoaded', () => GameEngine.init());
    })();
